// Group uploaded rows by file_path so we read each PDF only once
const rows = $input.all().map(i => i.json);
const groups = {};
for (const row of rows) {
  const key = row.file_path || row.source_pdf_url;
  if (!key) continue;
  if (!groups[key]) groups[key] = { file_path: row.file_path, source_pdf_url: row.source_pdf_url, placeholder_id: row.id };
}
return Object.values(groups).map(g => ({ json: g }));

const rawText = $input.first().json.content.parts[0].text;
const cleanString = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
const parsedArray = JSON.parse(cleanString);
return parsedArray.map(item => ({ json: item }));

let score = 0;
const r = $input.first().json;
if (r.case_number && r.amount && r.check_date) { score += 0.5; }
if (r.case_number && /^[0-9A-Z-]+$/.test(r.case_number)) { score += 0.2; }
if (typeof r.amount === 'number' && r.amount > 0) { score += 0.2; }
return [{ json: { ...r, ocr_confidence: score } }];

// ── Setup ───────────────────────────────────────────────────────────────
const scoredItems   = $('Score & Format').all();
const dbDuplicates  = $('Check Duplicates in DB').all().filter(i => i.json.id);
const allTenants    = $('Get All Tenants').all();

function dataScore(r) {
  return [r.case_number, r.check_number, r.amount, r.check_date, r.rent_from, r.rent_to]
    .filter(v => v != null && v !== '').length;
}

function checkKey(r) {
  if (!r.case_number && !r.check_number) return null;
  return (r.case_number || '') + '|' + (r.check_number || '') + '|' + (r.amount || '');
}

const batchGroups = {};
scoredItems.forEach((item, idx) => {
  const key = checkKey(item.json);
  if (!key) return;
  const score = dataScore(item.json);
  if (!batchGroups[key] || score > batchGroups[key].realScore) {
    batchGroups[key] = { realIdx: idx, realScore: score };
  }
});

return scoredItems.map((item, idx) => {
  const receipt = item.json;
  const tenant  = allTenants.find(t => t.json.case_number === receipt.case_number);
  const key     = checkKey(receipt);
  const inBatchDuplicate = key !== null && batchGroups[key] && batchGroups[key].realIdx !== idx;
  const dbDuplicate = dbDuplicates.find(d =>
    d.json.extracted_case_number === receipt.case_number &&
    d.json.extracted_check_number === receipt.check_number &&
    d.json.extracted_amount === receipt.amount
  );
  let dbDuplicateIsReal = false;
  if (dbDuplicate) {
    const dbScore = [
      dbDuplicate.json.extracted_case_number,
      dbDuplicate.json.extracted_check_number,
      dbDuplicate.json.extracted_amount,
      dbDuplicate.json.extracted_check_date,
      dbDuplicate.json.extracted_rent_from,
      dbDuplicate.json.extracted_rent_to
    ].filter(v => v != null && v !== '').length;
    dbDuplicateIsReal = dataScore(receipt) <= dbScore;
  }
  const isDuplicate   = inBatchDuplicate || (!!dbDuplicate && dbDuplicateIsReal);
  const duplicateRefId = (dbDuplicate && dbDuplicateIsReal) ? dbDuplicate.json.id : null;
  let status = 'needs_review';
  if (isDuplicate) { status = 'duplicate_suspected'; }
  else if (receipt.ocr_confidence > 0.75 && tenant) { status = 'processing'; }
  return {
    json: {
      extracted_case_number:  receipt.case_number,
      extracted_check_number: receipt.check_number,
      extracted_amount:       receipt.amount,
      extracted_check_date:   receipt.check_date,
      extracted_rent_from:    receipt.rent_from,
      extracted_rent_to:      receipt.rent_to,
      page_number:            receipt.page_number,
      matched_tenant_id:      tenant ? tenant.json.id : null,
      duplicate_suspected:    isDuplicate,
      duplicate_reference_id: duplicateRefId,
      status:                 status,
      ocr_confidence:         receipt.ocr_confidence,
      source_pdf_url:         $('Group by File Path').item.json.source_pdf_url,
      file_path:              $('Group by File Path').item.json.file_path
    }
  };
});

const blankCount  = $('Update Placeholder → blank_detected').all().length;
const insertCount = $('Insert Transaction Row').all().length;
return [{ json: { blank_pages: blankCount, processed_pages: insertCount, total_pages: blankCount + insertCount } }];

